mapper.select:
SELECT 
    cc.id, cc.course_id, cc.teacher_id, cc.user_id, 
    cc.score, cc.content, cc.status, cc.create_time, cc.update_time,
    u.name AS user_nickname, 
    u.avatar AS user_avatar
FROM course_comment cc
LEFT JOIN user u ON cc.user_id = u.id


        AND cc.course_id = #{params.courseId}


        AND cc.user_id = #{params.userId}


        AND cc.teacher_id = #{params.teacherId}


        AND cc.status = #{params.status}


        AND cc.score = #{params.score}


        AND (cc.content LIKE #{params.keyword} OR u.name LIKE #{params.keyword})



    ORDER BY ${params.orderBy}


    LIMIT #{params.limit}

SELECT 
    cc.id, cc.course_id, cc.teacher_id, cc.user_id, 
    cc.score, cc.content, cc.status, cc.create_time, cc.update_time,
    c.title AS course_name,
    u.name AS user_nickname, 
    u.avatar AS user_avatar
FROM course_comment cc
LEFT JOIN course c ON cc.course_id = c.id
LEFT JOIN user u ON cc.user_id = u.id
WHERE c.create_user = #{params.teacherId}

    AND cc.course_id = #{params.courseId}


    AND cc.status = #{params.status}


    AND cc.score = #{params.score}


    AND (cc.content LIKE #{params.keyword} OR u.name LIKE #{params.keyword})


    ORDER BY ${params.orderBy}


    ORDER BY cc.create_time DESC


    LIMIT #{params.limit}

SELECT 
    cc.id, cc.course_id, cc.teacher_id, cc.user_id, 
    cc.score, cc.content, cc.status, cc.create_time, cc.update_time,
    c.title AS course_name,
    u.name AS user_nickname, 
    u.avatar AS user_avatar
FROM course_comment cc
LEFT JOIN course c ON cc.course_id = c.id
LEFT JOIN user u ON cc.user_id = u.id


        AND cc.course_id = #{params.courseId}


        AND cc.user_id = #{params.userId}


        AND cc.status = #{params.status}


        AND (cc.content LIKE #{params.keyword} 
            OR u.name LIKE #{params.keyword} 
            OR c.title LIKE #{params.keyword})


ORDER BY cc.create_time DESC

SELECT 
    DATE(create_time) AS date,
    COUNT(id) AS commentCount,
    AVG(score) AS averageScore
FROM course_comment
WHERE create_time >= #{params.startDate}

    AND teacher_id = #{params.teacherId}


    AND course_id = #{params.courseId}

GROUP BY DATE(create_time)
ORDER BY date ASC
